import { createHash, randomUUID } from "node:crypto";
import type { BusinessSession, BusinessSessionRunner } from "../ports/persistence.ts";
import type { CommandEnvelope, CommandResult, AuthorityArtifactReference, WithholdingStatementSchemaPackRegisterPayload, WithholdingStatementSchemaPackDecisionPayload, WithholdingStatementFactPayload, WithholdingStatementFactDecisionPayload, WithholdingStatementBindingPayload, WithholdingStatementArtifactValidatePayload, WithholdingStatementArtifactExportPayload, WithholdingStatementForm } from "../commands.ts";
import { canonicalJson, computeCommandHash, computeResultHash } from "../commands.ts";
import { DomainError, IdempotencyConflictError, IdempotencyCorruptError } from "../../core/types.ts";
