  if (p.form === "24Q") { const runs = await session.query("SELECT id, period_start, period_end, payment_date, calculation_hash FROM payroll_pay_runs WHERE tenant_id = ? AND book_set_id = ? AND status = 'POSTED' AND period_end >= ? AND period_start <= ? ORDER BY payment_date, id", [tenantId, p.bookSetId, range.from, range.to]); for (const run of runs.rows) { const lines = await session.query("SELECT l.id, l.amount_minor, l.calculation_facts_json, c.component_code, c.label, e.employee_id, e.employee_deduction_minor FROM payroll_component_lines l JOIN payroll_salary_components c ON c.id = l.component_id AND c.tenant_id = l.tenant_id AND c.book_set_id = l.book_set_id JOIN payroll_pay_run_employees e ON e.id = l.pay_run_employee_id AND e.tenant_id = l.tenant_id AND e.book_set_id = l.book_set_id WHERE e.pay_run_id = ? AND l.tenant_id = ? AND l.book_set_id = ? AND (lower(c.component_code) LIKE '%tds%' OR lower(c.label) LIKE '%tds%') ORDER BY l.id", [run.id, tenantId, p.bookSetId]); for (const line of lines.rows) { const employee = await session.querySingle("SELECT pan_last_four, pan_verification_status FROM payroll_employees WHERE id = ? AND tenant_id = ? AND book_set_id = ?", [line.employee_id, tenantId, p.bookSetId]); if (!employee || String(employee.pan_verification_status) !== "VERIFIED") blockers.push("SALARY_PAN_UNVERIFIED"); sources.push({ sourceId: `payroll-tds:${String(run.id)}:${String(line.id)}`, sourceType: "SALARY_TDS", eventDate: String(run.payment_date), taxBaseMinor: safeMinor(line.amount_minor, "salary TDS amount"), taxAmountMinor: safeMinor(line.amount_minor, "salary TDS amount"), payeePanStatus: String(employee?.pan_verification_status ?? "MISSING"), sourceHash: hashCanonical({ runId: run.id, lineId: line.id, amount: line.amount_minor, calculationHash: run.calculation_hash, employeeId: line.employee_id }), depositAllocations: [] }); } } }
  const sourceIds = new Set(sources.map((row) => row.sourceId)); const deposits = new Map<string, { amount: bigint; allocations: Map<string, bigint> }>(); for (const row of facts.filter((fact) => String(fact.fact_type) === "CHALLAN")) { const depositId = row.deposit_id ? String(row.deposit_id) : undefined; if (!depositId) { blockers.push("CHALLAN_DEPOSIT_ID_MISSING"); continue; } const allocations = parse(row.allocations_json, "fact allocations") as Array<JsonRow>; const deposit = await session.querySingle("SELECT amount_minor FROM withholding_deposits WHERE id = ? AND tenant_id = ? AND book_set_id = ?", [depositId, tenantId, p.bookSetId]); if (!deposit) { blockers.push("CHALLAN_DEPOSIT_NOT_FOUND"); continue; } const allocationMap = new Map<string, bigint>(); let total = 0n; for (const allocation of allocations) { const id = text(allocation.sourceId, "allocation sourceId"); const amount = BigInt(safeMinor(allocation.amountMinor, "allocation amount")); if (!sourceIds.has(id)) blockers.push("CHALLAN_SOURCE_MISSING"); if (allocationMap.has(id)) blockers.push("CHALLAN_DUPLICATE_SOURCE"); allocationMap.set(id, amount); total += amount; } if (total !== BigInt(safeMinor(deposit.amount_minor, "deposit amount"))) blockers.push("CHALLAN_TOTAL_MISMATCH"); deposits.set(depositId, { amount: BigInt(safeMinor(deposit.amount_minor, "deposit amount")), allocations: allocationMap }); }
