async function bound(runnerSession: BusinessSession, tenantId: string, p: WithholdingStatementBindingPayload): Promise<SourceBuild> { const pack = await packRow(runnerSession, p.schemaPackId); if (String(pack.form) !== p.form || String(pack.financial_year) !== p.financialYear || String(pack.quarter) !== p.quarter || String(pack.filing_type) !== p.filingType) throw new DomainError("WITHHOLDING_STATEMENT_SCHEMA_PACK_BINDING_MISMATCH", "schema pack does not match exact form, period, and filing type"); if (await lifecycle(runnerSession, p.schemaPackId) !== "HUMAN_VERIFIED") throw new DomainError("WITHHOLDING_STATEMENT_SCHEMA_NOT_VERIFIED", "statement requires a HUMAN_VERIFIED schema pack"); return buildSource(runnerSession, tenantId, p, pack); }
function artifactView(row: JsonRow, status: string, reasons: string[] = []): JsonObject { return { artifactId: String(row.id), tenantId: String(row.tenant_id), bookSetId: String(row.book_set_id), deductorProfileId: String(row.deductor_profile_id), form: String(row.form), financialYear: String(row.financial_year), quarter: String(row.quarter), filingType: String(row.filing_type), schemaPackId: String(row.schema_pack_id), schemaPackHash: String(row.schema_pack_hash), sourceModelHash: String(row.source_model_hash), contentType: String(row.content_type), contentByteLength: Number(row.content_byte_length), contentHash: String(row.content_hash), bindings: { ...(parse(row.bindings_json, "bindings") as JsonRow), tan: undefined, pan: undefined }, status, statusReasons: reasons, createdAt: String(row.created_at), submitted: false, accepted: false }; }
async function artifactStatus(session: BusinessSession, row: JsonRow): Promise<{ status: string; reasons: string[] }> { try { const p = binding(parse(row.bindings_json, "bindings")); const current = await bound(session, String(row.tenant_id), p); if (current.blockers.length) return { status: "BLOCKED", reasons: current.blockers }; if (current.sourceModelHash !== String(row.source_model_hash)) return { status: "STALE", reasons: ["SOURCE_MODEL_CHANGED"] }; if (current.packHash !== String(row.schema_pack_hash)) return { status: "STALE", reasons: ["SCHEMA_PACK_CHANGED"] }; if (hashBytes(String(row.content_text)) !== String(row.content_hash)) return { status: "BLOCKED", reasons: ["CONTENT_HASH_MISMATCH"] }; const validation = await session.querySingle("SELECT status FROM withholding_statement_validation_runs WHERE artifact_id = ? AND tenant_id = ? AND book_set_id = ? ORDER BY created_at DESC, id DESC LIMIT 1", [row.id, row.tenant_id, row.book_set_id]); if (String(validation?.status) === "LOCAL_INVALID") return { status: "LOCAL_INVALID", reasons: ["LATEST_LOCAL_VALIDATION_FAILED"] }; const exported = await session.querySingle("SELECT id FROM withholding_statement_export_activities WHERE artifact_id = ? AND tenant_id = ? AND book_set_id = ? LIMIT 1", [row.id, row.tenant_id, row.book_set_id]); return exported ? { status: "EXPORTED", reasons: [] } : String(validation?.status) === "LOCAL_VALID" ? { status: "LOCAL_VALID", reasons: [] } : { status: "PREPARED", reasons: [] }; } catch (error) { return { status: "BLOCKED", reasons: [error instanceof DomainError ? error.code : "UPSTREAM_CHANGED"] }; } }
export async function previewWithholdingStatement(runner: BusinessSessionRunner, tenantId: string, payload: WithholdingStatementBindingPayload): Promise<JsonObject> { return runner.withBusinessSession("read", async (session) => { const p = binding(payload); const build = await bound(session, tenantId, p); const mapped = build.blockers.length ? undefined : evaluateMapping(parse(build.pack.mapping_spec_json, "mapping spec") as Mapping, build.root); const content = mapped === undefined ? undefined : `${canonicalJson(mapped)}\n`; return { schemaVersion: 1, status: build.blockers.length ? "BLOCKED" : "PREVIEW", blockerCodes: build.blockers, ...(content ? { contentByteLength: Buffer.byteLength(content), contentHash: hashBytes(content) } : {}), bindings: build.bindings, sourceModelHash: build.sourceModelHash, schemaPackHash: build.packHash }; }); }
export async function prepareWithholdingStatement(runner: BusinessSessionRunner, envelope: CommandEnvelope<WithholdingStatementBindingPayload>): Promise<CommandResult<JsonObject>> { validateCommandEnvelope(envelope); actor(envelope.actor.kind); const p = binding(envelope.payload); const requestHash = computeCommandHash(PREPARE, envelope, p); return runner.withBusinessSession("write", async (session) => { const prior = await replay<JsonObject>(session, envelope.tenantId, envelope.requestId, requestHash); if (prior) return prior; const build = await bound(session, envelope.tenantId, p); if (build.blockers.length) throw new DomainError("WITHHOLDING_STATEMENT_BLOCKED", "statement source model is blocked", { blockerCodes: build.blockers }); const mapped = evaluateMapping(parse(build.pack.mapping_spec_json, "mapping spec") as Mapping, build.root); const content = `${canonicalJson(mapped)}\n`; if (Buffer.byteLength(content) > MAX_ARTIFACT_JSON) throw new DomainError("WITHHOLDING_STATEMENT_ARTIFACT_TOO_LARGE", "statement artifact exceeds the V1 size limit"); const contentHash = hashBytes(content); const existing = await session.querySingle("SELECT * FROM withholding_statement_artifacts WHERE tenant_id = ? AND book_set_id = ? AND form = ? AND financial_year = ? AND quarter = ? AND filing_type = ? AND content_hash = ?", [envelope.tenantId, p.bookSetId, p.form, p.financialYear, p.quarter, p.filingType, contentHash]); if (existing) return finish(session, { ...envelope, bookSetId: p.bookSetId }, PREPARE, requestHash, { ...artifactView(existing, "PREPARED"), duplicate: true }, "WithholdingStatementArtifact", String(existing.id)); const id = randomUUID(); const now = new Date().toISOString(); await session.execute("INSERT INTO withholding_statement_artifacts (id,tenant_id,book_set_id,deductor_profile_id,form,financial_year,quarter,filing_type,schema_pack_id,schema_pack_hash,source_model_hash,content_type,content_text,content_byte_length,content_hash,bindings_json,created_at,created_by_actor_kind,created_by_actor_id,request_id,request_hash) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)", [id, envelope.tenantId, p.bookSetId, p.deductorProfileId, p.form, p.financialYear, p.quarter, p.filingType, p.schemaPackId, build.packHash, build.sourceModelHash, "application/json", content, Buffer.byteLength(content), contentHash, canonicalJson(build.bindings), now, envelope.actor.kind, envelope.actor.id, envelope.requestId, requestHash]); const row = await session.querySingle("SELECT * FROM withholding_statement_artifacts WHERE id = ?", [id]) as JsonRow; return finish(session, { ...envelope, bookSetId: p.bookSetId }, PREPARE, requestHash, { ...artifactView(row, "PREPARED"), duplicate: false }, "WithholdingStatementArtifact", id); }); }
export async function validateWithholdingStatement(runner: BusinessSessionRunner, envelope: CommandEnvelope<WithholdingStatementArtifactValidatePayload>): Promise<CommandResult<JsonObject>> { validateCommandEnvelope(envelope); actor(envelope.actor.kind); const p = envelope.payload; const expected = sha(p.expectedArtifactHash, "expectedArtifactHash"); const requestHash = computeCommandHash(VALIDATE, envelope, p); return runner.withBusinessSession("write", async (session) => { const prior = await replay<JsonObject>(session, envelope.tenantId, envelope.requestId, requestHash); if (prior) return prior; const row = await session.querySingle("SELECT * FROM withholding_statement_artifacts WHERE id = ? AND tenant_id = ? AND book_set_id = ?", [p.artifactId, envelope.tenantId, p.bookSetId]); if (!row) throw new DomainError("WITHHOLDING_STATEMENT_ARTIFACT_NOT_FOUND", "statement artifact does not belong to tenant and BookSet"); if (String(row.content_hash) !== expected) throw new DomainError("WITHHOLDING_STATEMENT_ARTIFACT_CAS_MISMATCH", "expected artifact hash does not match"); const state = await artifactStatus(session, row); if (["STALE", "BLOCKED"].includes(state.status)) throw new DomainError("WITHHOLDING_STATEMENT_NOT_VALIDATABLE", "statement artifact is not current", state); const pack = await packRow(session, String(row.schema_pack_id)); const diagnostics = validateValue(parse(pack.validation_schema_json, "validation schema") as Schema, parse(row.content_text, "statement content")) as Diagnostic[]; const body = { schemaVersion: 1, artifactId: p.artifactId, artifactHash: expected, schemaPackId: String(pack.id), schemaPackHash: String(pack.canonical_hash), status: diagnostics.length ? "LOCAL_INVALID" : "LOCAL_VALID", diagnostics }; const validationHash = hashCanonical(body); const id = randomUUID(); const now = new Date().toISOString(); await session.execute("INSERT INTO withholding_statement_validation_runs (id,tenant_id,book_set_id,artifact_id,artifact_hash,schema_pack_hash,validation_hash,status,diagnostics_json,created_at,created_by_actor_kind,created_by_actor_id,request_id,request_hash) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?)", [id, envelope.tenantId, p.bookSetId, p.artifactId, expected, String(pack.canonical_hash), validationHash, body.status, canonicalJson(diagnostics), now, envelope.actor.kind, envelope.actor.id, envelope.requestId, requestHash]); return finish(session, { ...envelope, bookSetId: p.bookSetId }, VALIDATE, requestHash, { validationId: id, validationHash, ...body }, "WithholdingStatementValidationRun", id); }); }
export async function exportWithholdingStatement(runner: BusinessSessionRunner, envelope: CommandEnvelope<WithholdingStatementArtifactExportPayload>): Promise<CommandResult<JsonObject>> { validateCommandEnvelope(envelope); if (envelope.actor.kind !== "HUMAN") throw new DomainError("WITHHOLDING_STATEMENT_EXPORT_HUMAN_REQUIRED", "statement export requires a HUMAN actor"); const p = envelope.payload; const expectedArtifactHash = sha(p.expectedArtifactHash, "expectedArtifactHash"); const expectedValidationHash = sha(p.expectedValidationHash, "expectedValidationHash"); const requestHash = computeCommandHash(EXPORT, envelope, p); return runner.withBusinessSession("write", async (session) => { const prior = await replay<JsonObject>(session, envelope.tenantId, envelope.requestId, requestHash); if (prior) return prior; const row = await session.querySingle("SELECT * FROM withholding_statement_artifacts WHERE id = ? AND tenant_id = ? AND book_set_id = ?", [p.artifactId, envelope.tenantId, p.bookSetId]); if (!row) throw new DomainError("WITHHOLDING_STATEMENT_ARTIFACT_NOT_FOUND", "statement artifact does not belong to tenant and BookSet"); if (String(row.content_hash) !== expectedArtifactHash) throw new DomainError("WITHHOLDING_STATEMENT_ARTIFACT_CAS_MISMATCH", "expected artifact hash does not match"); const state = await artifactStatus(session, row); if (["STALE", "BLOCKED", "LOCAL_INVALID"].includes(state.status)) throw new DomainError("WITHHOLDING_STATEMENT_EXPORT_BLOCKED", "only a current LOCAL_VALID statement can be exported", state); const validation = await session.querySingle("SELECT status, validation_hash FROM withholding_statement_validation_runs WHERE artifact_id = ? AND tenant_id = ? AND book_set_id = ? ORDER BY created_at DESC, id DESC LIMIT 1", [p.artifactId, envelope.tenantId, p.bookSetId]); if (!validation || String(validation.status) !== "LOCAL_VALID" || String(validation.validation_hash) !== expectedValidationHash) throw new DomainError("WITHHOLDING_STATEMENT_VALIDATION_CAS_MISMATCH", "latest validation is not the exact requested LOCAL_VALID validation"); const id = randomUUID(); const now = new Date().toISOString(); await session.execute("INSERT INTO withholding_statement_export_activities (id,tenant_id,book_set_id,artifact_id,artifact_hash,validation_hash,actor_kind,actor_id,request_id,request_hash,created_at) VALUES (?,?,?,?,? ,?,'HUMAN',?,?,?,?)", [id, envelope.tenantId, p.bookSetId, p.artifactId, expectedArtifactHash, expectedValidationHash, envelope.actor.id, envelope.requestId, requestHash, now]); return finish(session, { ...envelope, bookSetId: p.bookSetId }, EXPORT, requestHash, { exportActivityId: id, artifactId: p.artifactId, artifactHash: expectedArtifactHash, validationHash: expectedValidationHash, status: "EXPORTED", submitted: false, accepted: false }, "WithholdingStatementExportActivity", id); }); }
export async function showWithholdingStatement(runner: BusinessSessionRunner, tenantId: string, bookSetId: string, artifactId: string): Promise<JsonObject> { return runner.withBusinessSession("read", async (session) => { const row = await session.querySingle("SELECT * FROM withholding_statement_artifacts WHERE id = ? AND tenant_id = ? AND book_set_id = ?", [artifactId, tenantId, bookSetId]); if (!row) throw new DomainError("WITHHOLDING_STATEMENT_ARTIFACT_NOT_FOUND", "statement artifact does not belong to tenant and BookSet"); const state = await artifactStatus(session, row); return artifactView(row, state.status, state.reasons); }); }
export async function statusWithholdingStatement(runner: BusinessSessionRunner, tenantId: string, bookSetId: string, artifactId: string): Promise<JsonObject> { const result = await showWithholdingStatement(runner, tenantId, bookSetId, artifactId); return { artifactId: result.artifactId, tenantId, bookSetId, status: result.status, statusReasons: result.statusReasons }; }
export async function contentWithholdingStatement(runner: BusinessSessionRunner, tenantId: string, bookSetId: string, artifactId: string, revealSensitive = false, actorKind?: string): Promise<JsonObject> { return runner.withBusinessSession("read", async (session) => { const row = await session.querySingle("SELECT * FROM withholding_statement_artifacts WHERE id = ? AND tenant_id = ? AND book_set_id = ?", [artifactId, tenantId, bookSetId]); if (!row) throw new DomainError("WITHHOLDING_STATEMENT_ARTIFACT_NOT_FOUND", "statement artifact does not belong to tenant and BookSet"); const state = await artifactStatus(session, row); const metadata = artifactView(row, state.status, state.reasons); if (!revealSensitive) return { ...metadata, revealed: false }; if (actorKind !== "HUMAN") throw new DomainError("WITHHOLDING_STATEMENT_SENSITIVE_HUMAN_REQUIRED", "raw statement content requires an explicit HUMAN actor"); return { ...metadata, revealed: true, content: parse(row.content_text, "statement content") }; }); }
